test_that("stateless preprocessing agrees with frozen Python n4m oracle", {
    row_matrix <- function(values) matrix(scan(text = values, sep = ",", quiet = TRUE),
                                          nrow = 3L, byrow = TRUE)
    X <- row_matrix(paste0(
        "1.5273016397555954,1.4497568011283815,1.3540476506568899,1.3557506015471605,1.4808818302521505,1.6419781238206304,1.7185101545272734,1.6676965879338459,1.5638370444754881,",
        "1.40404765065689,1.5008818302521505,1.7085101545272736,1.5238370444754883,1.554879791479939,1.7986850297972818,1.6496935356668907,1.6148617854519653,1.8778123351018678,",
        "1.5808818302521503,1.7076965879338459,1.6048797914799391,1.8010402976219964,1.6348617854519651,1.8871317893950477,1.6732190293190725,1.9638926299766304,1.7216755726269992"))
    expected <- list(
        local_snv = row_matrix(paste0(
            "1.5213817768086109,0.34216329188478006,-1.1555606009471313,-0.95448578237378368,-0.19801944771636615,0.51275061611898487,1.2453370274020419,0.3114716258321033,-1.830973934788767,",
            "-1.3078655961178969,-0.26902153864384337,1.7201760448653969,-0.80547625728055217,-0.91825123777595952,1.775967815303898,-0.41189312512430631,-0.89618716561856826,1.9753092535192172,",
            "-1.0969942598952038,0.34259050373838629,-0.76330102282795698,0.70542764090165577,-0.79818534557838539,0.76398076164676365,-0.80830723986198882,0.99743712914829807,-0.57136930014590281")),
        robust_snv = row_matrix(paste0(
            "0,-0.45609418117054845,-1.0190250916941557,-1.0090088739081398,-0.2730266176366305,0.6744907594765952,1.1246279252300826,0.8257586199601501,0.21488967924173424,",
            "-1.5183626505228986,-0.82092648603425078,0.6744907594765952,-0.6555944036036836,-0.43201286972310682,1.3239641107707794,0.25087135940906102,0,1.8938687100415696,",
            "-0.91634864853057785,0,-0.74294217959445086,0.6744907594765952,-0.5262957879696093,1.2965778381289867,-0.24913081741307144,1.8512427195109844,0.1010105130157859")),
        area = row_matrix(paste0(
            "0.12504320820379233,0.11869445878246399,0.11085856119819246,0.1109979851581949,0.12124272652196262,0.134431998931024,0.14069782776326514,0.13653762049200471,0.12803443410199175,",
            "0.10806784805625304,0.11552105764088259,0.13150195842401538,0.11728789269211877,0.11967721535147166,0.13844260941588987,0.1269749144684825,0.12429395681864859,0.1445329423207283,",
            "0.11353646658271038,0.12264410462509705,0.1152599627168632,0.12934790422156944,0.11741322274651704,0.13553086084217131,0.12016798015670759,0.14104370465173141,0.12364805349597582")),
        detrend = row_matrix(paste0(
            "0.086976537555985445,0.0035326063807010755,-0.10503357928850843,-0.12314560624560333,-0.024787298037626249,0.10257813238419344,0.13842135729452876,0.039961042255145962,-0.11850319229881445,",
            "-0.054736964620095696,-0.0034413083185622639,0.16025848336113491,-0.066733168587775227,-0.076398972782148133,0.12830770503467237,-0.058172358897940368,-0.12888268821678595,0.09979927302749747,",
            "-0.011238718127452696,0.063544276770109986,-0.083840602925220553,0.075215499518121787,-0.12060373680791514,0.10948922252187088,-0.11913690262469179,0.16428701250498778,-0.077716050829812922")))
    actual <- list(
        local_snv = local_snv_transform(X, window = 5L),
        robust_snv = robust_snv_transform(X),
        area = area_normalization_transform(X, method = "trapz"),
        detrend = detrend_transform(X, polyorder = 2L))
    for (name in names(expected))
        expect_equal(actual[[name]], expected[[name]], tolerance = 1e-12,
                     info = paste("Python n4m", name))
    expect_error(local_snv_transform(X, window = 4L))
    expect_error(area_normalization_transform(X, method = "unknown"))
})
